// Panels are hidden via JS so content stays visible in no-JS / reader-mode environments.
(function () {
  'use strict';

  document.querySelectorAll('button[aria-expanded]').forEach(function (btn) {
    const panel = btn.closest('.example').querySelector('.details');
    if (!panel) return;

    // Collapse on init
    btn.setAttribute('aria-expanded', 'false');
    panel.hidden = true;

    btn.addEventListener('click', function () {
      const isOpen = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', String(!isOpen));
      panel.hidden = isOpen;
    });

    // Escape collapses the open panel and returns focus to the trigger
    panel.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') {
        btn.setAttribute('aria-expanded', 'false');
        panel.hidden = true;
        btn.focus();
      }
    });
